#include <iostream>
using namespace std;

int main() {
    int elev[3][3];
    for (int r = 0; r < 3; r++) {
        for (int c = 0; c < 3; c++) {
            cin >> elev[r][c];
        }
    }

    int max_elev = elev[0][0];
    int peak_r = 0;
    int peak_c = 0;

    for (int r = 0; r < 3; r++) {
        for (int c = 0; c < 3; c++) {
            if (elev[r][c] > max_elev) {
                max_elev = elev[r][c];
                peak_r = r;
                peak_c = c;
            }
        }
    }

    cout << "PEAK ELEVATION: " << max_elev << endl;
    cout << "AT COORDINATES: (" << peak_r << ", " << peak_c << ")" << endl;

    return 0;
}

