#include <iostream>
using namespace std;

int main() {
    int grid[3][3];
    for (int r = 0; r < 3; r++) {
        for (int c = 0; c < 3; c++) {
            cin >> grid[r][c];
        }
    }

    int safe_count = 0;
    int hazard_count = 0;
    int min_rough = grid[0][0];

    for (int r = 0; r < 3; r++) {
        for (int c = 0; c < 3; c++) {
            if (grid[r][c] <= 15) {
                safe_count++;
            }
            if (grid[r][c] > 50) {
                hazard_count++;
            }
            if (grid[r][c] < min_rough) {
                min_rough = grid[r][c];
            }
        }
    }

    cout << "SAFE SECTORS: " << safe_count << endl;
    cout << "HAZARD SECTORS: " << hazard_count << endl;
    cout << "BEST LANDING ROUGHNESS: " << min_rough << endl;

    return 0;
}
